import {
    Table,
    TableNameColumn,
    DurationColumn,
    GuidColumn,
    BooleanColumn,
    StringColumn,
    ConditionsColumn,
    ReferenceColumn,
    IntegerColumn,
} from '@servicenow/sdk/core'

export const sc_cat_item_delivery_plan = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Execution Plan',
    name: 'sc_cat_item_delivery_plan',
    schema: {
        parent_table: TableNameColumn({
            attributes: {
                allow_public: true,
                base_start: true,
                base_table: 'task',
            },
            default: 'sc_req_item',
            label: [
                {
                    hint: 'Class of record to which this plan applies',
                    label: 'Parent table',
                    plural: 'Parent tables',
                    language: 'en',
                },
            ],
        }),
        total_delivery_time: DurationColumn({
            label: [
                {
                    hint: 'Time it takes to complete this execution plan',
                    label: 'Total delivery time',
                    plural: 'Total delivery times',
                    language: 'en',
                },
            ],
            maxLength: 40,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        script: StringColumn({
            label: 'Script',
            maxLength: 8000,
        }),
        task_table: TableNameColumn({
            attributes: {
                allow_public: true,
                base_start: true,
                base_table: 'task',
            },
            default: 'sc_task',
            label: [
                {
                    hint: 'Class of child tasks to create',
                    label: 'Task table',
                    plural: 'Task tables',
                    language: 'en',
                },
            ],
        }),
        short_description: StringColumn({
            label: 'Short description',
            maxLength: 120,
        }),
        condition: ConditionsColumn({
            dependent: 'parent_table',
            label: 'Conditions',
            maxLength: 1000,
        }),
        calendar: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'On Calendar',
            referenceTable: 'sys_calendar',
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),
        order: IntegerColumn({
            default: '100',
            label: 'Order',
        }),
        advanced: BooleanColumn({
            default: false,
            label: 'Advanced',
        }),
    },
})
